def _handle_a(item):
    value = item["value"] * 2
    category = "high" if value > 100 else "low"
    return {"id": item["id"], "value": value, "category": category}


def _handle_b(item):
    return {"id": item["id"], "value": item["value"] + 50, "category": "adjusted"}


def _handle_c(item):
    if item["value"] < 0:
        return {"id": item["id"], "value": 0, "category": "clamped"}
    return {"id": item["id"], "value": item["value"], "category": "passthrough"}


HANDLERS = {
    "A": _handle_a,
    "B": _handle_b,
    "C": _handle_c,
}


def dispatch(item):
    handler = HANDLERS.get(item.get("type"))
    if handler is None:
        return None
    return handler(item)


def process_data(data):
    return [result for result in map(dispatch, data) if result is not None]

