export interface Preferences {
  theme: string;
  notifications: boolean;
  language: string;
}

export interface User {
  id: number;
  name: string;
  email: string;
  preferences: Preferences;
  tags: string[];
  last_login: string;
  metadata?: unknown | null;
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function validateUser(input: unknown): input is User {
  if (!isPlainObject(input)) {
    return false;
  }

  const user = input as Record<string, unknown>;

  if (!Number.isInteger(user.id)) {
    return false;
  }

  if (typeof user.name !== "string" || user.name.length === 0) {
    return false;
  }

  if (typeof user.email !== "string" || !user.email.includes("@")) {
    return false;
  }

  if (!isPlainObject(user.preferences)) {
    return false;
  }

  const preferences = user.preferences as Record<string, unknown>;

  if (typeof preferences.theme !== "string") {
    return false;
  }

  if (typeof preferences.notifications !== "boolean") {
    return false;
  }

  if (typeof preferences.language !== "string") {
    return false;
  }

  const tags = user.tags;
  if (!Array.isArray(tags) || !tags.every((tag) => typeof tag === "string")) {
    return false;
  }

  if (
    typeof user.last_login !== "string" ||
    Number.isNaN(Date.parse(user.last_login))
  ) {
    return false;
  }

  const metadata = user.metadata;

  if (metadata !== undefined && metadata !== null) {
    if (typeof metadata === "function") {
      return false;
    }
  }

  return true;
}
