#!/usr/bin/env python3
"""Count log levels in .log files in a directory."""

import argparse
import re
import sys
from pathlib import Path

LEVELS = ("INFO", "WARN", "ERROR", "DEBUG")
PATTERNS = {
    "INFO": re.compile(r"\bINFO\b"),
    "WARN": re.compile(r"\bWARN(?:ING)?\b"),
    "ERROR": re.compile(r"\bERROR\b"),
    "DEBUG": re.compile(r"\bDEBUG\b"),
}


def parse_args(argv=None):
    parser = argparse.ArgumentParser(
        description="Read a directory of .log files and summarize log-level counts."
    )
    parser.add_argument("directory", type=Path, help="Directory containing .log files")
    parser.add_argument(
        "--min-errors",
        type=int,
        default=0,
        metavar="N",
        help="Only show files with at least N ERROR occurrences (default: 0)",
    )
    args = parser.parse_args(argv)

    if args.min_errors < 0:
        parser.error("--min-errors must be a non-negative integer")

    return args


def count_levels(path: Path) -> dict:
    counts = {level: 0 for level in LEVELS}

    try:
        with path.open("r", encoding="utf-8", errors="replace") as handle:
            for line in handle:
                for level, pattern in PATTERNS.items():
                    counts[level] += len(pattern.findall(line))
    except OSError as exc:
        print(f"Warning: could not read {path}: {exc}", file=sys.stderr)

    return counts


def main(argv=None) -> int:
    args = parse_args(argv)
    directory = args.directory

    if not directory.is_dir():
        print(f"Error: {directory} is not a directory", file=sys.stderr)
        return 1

    log_files = sorted(path for path in directory.glob("*.log") if path.is_file())
    rows = []

    for path in log_files:
        counts = count_levels(path)
        if counts["ERROR"] >= args.min_errors:
            rows.append((path.name, counts))

    if not rows:
        if not log_files:
            print("No .log files found.")
        else:
            print("No files meet the --min-errors threshold.")
        return 0

    table = [("file", *LEVELS)]
    for name, counts in rows:
        table.append((name, *(counts[level] for level in LEVELS)))

    widths = [max(len(str(cell)) for cell in column) for column in zip(*table)]

    for row in table:
        print(" | ".join(str(cell).ljust(widths[index]) for index, cell in enumerate(row)))

    return 0


if __name__ == "__main__":
    sys.exit(main())
